import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.IdClass;
import jakarta.persistence.Table;
import java.io.Serializable;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Objects;

/** The value a dated setting of a sheet takes from a date on (the floor, the late percent, the terms
 *  of the sheet and of each grade, the clerk limit, the cap); in force until a later from-date of the
 *  same key. A null value is blank: no limit, no cap. */
@Entity
@Table(name = "setting_value")
@IdClass(SettingValue.Key.class)
public class SettingValue {

    /** The key of a setting value: its sheet, setting and from-date. */
    public static class Key implements Serializable {
        private String sheetId;
        private String key;
        private LocalDate from;

        protected Key() {
        }

        public Key(String sheetId, String key, LocalDate from) {
            this.sheetId = sheetId;
            this.key = key;
            this.from = from;
        }

        @Override
        public boolean equals(Object o) {
            return o instanceof Key k && Objects.equals(sheetId, k.sheetId) && Objects.equals(key, k.key)
                    && Objects.equals(from, k.from);
        }

        @Override
        public int hashCode() {
            return Objects.hash(sheetId, key, from);
        }
    }

    @Id
    @Column(name = "sheet_id")
    private String sheetId;

    @Id
    @Column(name = "setting_key")
    private String key;

    @Id
    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "setting", precision = 14, scale = 2)
    private BigDecimal value;

    protected SettingValue() {
    }

    public SettingValue(String sheetId, String key, LocalDate from, BigDecimal value) {
        this.sheetId = sheetId;
        this.key = key;
        this.from = from;
        this.value = value;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFrom() {
        return from;
    }

    public BigDecimal getValue() {
        return value;
    }

    public void setValue(BigDecimal value) {
        this.value = value;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A revision of a dated setting's value in its sheet's history: the value a setting takes from a
 *  from-date after a change, recorded on the sheet's today then. */
@Entity
@Table(name = "setting_revision")
public class SettingRevision {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "setting_key", nullable = false)
    private String key;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    /** The sheet's today when the revision was recorded. */
    @Column(name = "recorded_on", nullable = false)
    private LocalDate recordedOn;

    @Column(name = "setting", precision = 14, scale = 2)
    private BigDecimal value;

    protected SettingRevision() {
    }

    /** A revision of the setting value as it is now, recorded on the day. */
    public SettingRevision(SettingValue value, LocalDate recordedOn) {
        this.sheetId = value.getSheetId();
        this.key = value.getKey();
        this.from = value.getFrom();
        this.recordedOn = recordedOn;
        this.value = value.getValue();
    }

    /** Which setting value the revision is of: its setting and from-date. */
    public String key() {
        return key + ":" + from;
    }

    /** Which setting value a value is (see {@link #key()}). */
    public static String key(SettingValue value) {
        return value.getKey() + ":" + value.getFrom();
    }

    /** Whether the setting value is now as this revision has it. */
    public boolean matches(SettingValue now) {
        return value == null ? now.getValue() == null : now.getValue() != null && value.compareTo(now.getValue()) == 0;
    }

    /** The setting value as this revision has it, detached: for working out figures only, never saved. */
    public SettingValue toValue() {
        return new SettingValue(sheetId, key, from, value);
    }

    public LocalDate getRecordedOn() {
        return recordedOn;
    }
}
-- How many proofs a claim has. A claim whose due is above the sheet's proof threshold in force on its
-- date cannot be settled or approved while it has none. The threshold is a dated setting
-- (setting_value key 'proof-threshold'; blank: none).
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- Dated settings: a figure a setting takes from a date on (the floor, the late percent, the terms of
-- the sheet and of each grade, the clerk limit and the cap). The value in force on a date is the one
-- with the latest from-date on or before it; before every from-date the sheet's starting value
-- (floor 1.00, late percent 0.00, terms 14; none for the others). A null value is blank (no limit,
-- no cap).
CREATE TABLE setting_value (
    sheet_id    VARCHAR(100)   NOT NULL,
    setting_key VARCHAR(20)    NOT NULL,
    from_date   DATE           NOT NULL,
    setting     DECIMAL(14, 2),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- The values already set carry over from the earliest date, so they stay in force everywhere.
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'floor', DATE '0001-01-01', due_floor FROM sheet WHERE due_floor <> 1.00;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'late-pct', DATE '0001-01-01', late_pct FROM sheet WHERE late_pct <> 0.00;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'terms', DATE '0001-01-01', terms FROM sheet WHERE terms <> 14;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'clerk-limit', DATE '0001-01-01', clerk_limit FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'cap', DATE '0001-01-01', cap FROM sheet WHERE cap IS NOT NULL;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', terms FROM grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN cap;
DROP TABLE grade_terms;
-- The sheet's grace days: when its today is changed, an open period whose to-date plus them is before
-- the new today is closed; null (blank) is off.
ALTER TABLE sheet ADD COLUMN grace_days INT;

